import React, { useEffect, useState } from "react";



import { getStore, updStore, gen16CodeId,  fetchEncryptStream,  ObjectKeys, parseFloatToDecimal, qryStore, generateComprobanteId, parseDateMMDDYYYY, dayNames2ES } from "../../../stores/Utils";

import { CheckBoxSlide_Cmpt, TextInput_Cmpt } from "../../../components";


import "./dashboard.css"
import { DateCalComponent_Cmpt } from "../../Inventory";

import { GrayButton } from "../../../components/Buttons";
import { useNavigate } from "react-router";
import { CloseModal } from "../../../components/DialogHRM";



const CheckBoxSlide = CheckBoxSlide_Cmpt();
const TextInput = TextInput_Cmpt();


const DateCalComponent = DateCalComponent_Cmpt();



const frmNm = "paystub_employee_2Acc";




const PaystubEmployee2Accc  = ({data, confirm, item}) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const navigate = useNavigate();


	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			let frm2 = getStore(frmNm) || {};
			
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};



	const save  =  ()  => {
	
		if(item.w2Taxes){
			saveW2()
		}else{
			save1099()
		}
	};


	let ffm22 = getStore(frmNm) || {};

	let date2 = (new Date()).getTime()+800;
	if(ffm22["date"]){
		let nn = (new Date(ffm22["date"])).getTime();
		date2 = nn
	}

	let employeeDt = getStore("employees_ids")?.[item?.["employeeId"]];
	
	let description2 = `Check No ${ffm22.document?ffm22.document:""} - Salary ${parseDateMMDDYYYY(date2)} - ${employeeDt?.name}`.toUpperCase();

	
	const save1099 = async (f) => {
		let ffm = getStore(frmNm) || {};
		let date = (new Date()).getTime()+800;
		if(ffm["date"]){
			let nn = (new Date(ffm["date"])).getTime();
			date = nn?nn:date;
		}
		ffm["date"] = date; 

		ffm["amount"] = item?.grossPay;

		if(!ffm["description"]){
			ffm["description"] =description2;
		}

		let comprobanteId = await generateComprobanteId(ffm["date"]);

		let commonflds = {
			date: ffm.date,
			comprobanteId: comprobanteId,
			description: ffm.description,
			businessId:  getStore("profileUser")?.businessId,
			year: (new Date(ffm["date"])).getFullYear()
		}
	
		delete ffm.date;
		

		ffm["document"] = ffm["document"]?.trim();
		ffm["employeeId"] = item?.employeeId;
		let comp2save = [];
		
	
		let frmSlr = {...ffm}

		let amountBank = parseFloatToDecimal(ffm["amount"],2);
		
		item.otherDeductions && ObjectKeys(item.otherDeductions).map(othDD=>{
			let nnfrm = {...ffm}
			
			let itemODD = item.otherDeductions[othDD];
			let dataAcc = {...getStore("global_account_params")?.[othDD]};
			nnfrm["account"] =  dataAcc["account"];
			nnfrm["subAccount"] = dataAcc["subAccount"];
			nnfrm["operationId"] = gen16CodeId();
			

			
			let amountT = itemODD.amount*1; 

			if(othDD==="Overpayments"){
				nnfrm["type"] ="credit";
				amountBank = amountBank*1 + amountT;
				nnfrm["amount"] = amountT *-1;
			}
			else if(othDD==="Underpayments"){
				nnfrm["type"] ="debit";
				amountBank = amountBank*1 + amountT;
				nnfrm["amount"] = amountT;
			}
			
			comp2save.push(nnfrm)
		})

		
		frmSlr["account"] = getStore("global_account_params")?.salary.account;

		let amountSlr = parseFloatToDecimal(ffm["amount"],2);
		frmSlr["type"] = "debit";
		frmSlr["operationId"] = gen16CodeId();
		frmSlr["amount"] =amountSlr*1;
		
		comp2save.push(frmSlr)



		let frmBnk = {...ffm}

		frmBnk["account"] = getStore("global_account_params")?.cash_bank.account;
		if(ffm?.futureSlipCheck){
			frmBnk["account"] = getStore("global_account_params")?.futureSlipCheck?.account;
			frmBnk["subAccount"] = getStore("global_account_params")?.futureSlipCheck?.subAccount;
		}
		
		
		frmBnk["type"] = "credit";
		frmBnk["operationId"] = gen16CodeId();
		frmBnk["amount"] =amountBank*1;

		comp2save.push(frmBnk)

		let bdyq2 = {...getStore(qryStore())?.add_multi_opera};
		bdyq2.params = commonflds;
		bdyq2.form=comp2save;

		

		fetch2Server(bdyq2, comprobanteId, ffm["document"]);


	}


	

	const saveW2 = async (f) => {

		let ffm = getStore(frmNm) || {};
		let date = (new Date()).getTime()+800;
		if(ffm["date"]){
			let nn = (new Date(ffm["date"])).getTime();
			date = nn?nn:date;
		}
		ffm["date"] = date; 

		const cash_amount = ffm.cash_amount;

		delete ffm.cash_amount;

		let comprobanteId = await generateComprobanteId(ffm["date"]);

		ffm["comprobanteId"] =comprobanteId;
		ffm["document"] = ffm["document"]?.trim();


		if(!ffm["description"]){
			ffm["description"] = description2;
		}

		ffm["amount"] = item?.grossPay;

		ffm["employeeId"] = item?.employeeId;
		let comp2save = [];
		
	
		let totalC = 0;


		let commonflds = {
			date: ffm.date,
			comprobanteId: comprobanteId,
			description: ffm.description,
			businessId:  getStore("profileUser")?.businessId,
			year: (new Date(ffm["date"])).getFullYear()
		}
	
		delete ffm.date;
		


		item.w2Taxes && ObjectKeys(item.w2Taxes).map(tx=>{
			
			let nnfrm = {...ffm}
			// let dataAcc = {...getStore("global_account_params")?.w2_params?.[tx]?.account};
			let itemW2 = item.w2Taxes[tx];
			let dataAcc = itemW2.account;
			nnfrm["account"] =  dataAcc["account"];
			nnfrm["subAccount"] = dataAcc["subAccount"];

			
			let amountT = itemW2.amount ? itemW2.amount  : itemW2.percent / 100 * item.grossPay; 
		
			let amount = parseFloatToDecimal(amountT,2)
			nnfrm["type"] = "credit";
			nnfrm["operationId"] = gen16CodeId();
			
			
			
			if(tx === "socialSecurity"){
				let frmSS = {...ffm};
				frmSS["account"] = getStore("global_account_params")?.socialsecurity_tax_expenses?.account;
				frmSS["type"] = "debit";
				frmSS["amount"] = amount*1;
				frmSS["operationId"] = gen16CodeId();
				totalC += amount*1;
				nnfrm["amount"] =amount*2;
				comp2save.push(frmSS)
			}
			else if( tx === "medicareTax"){
				let frmSM = {...ffm};
				frmSM["account"] = getStore("global_account_params")?.medicare_tax_expenses?.account;
				frmSM["type"] = "debit";
				frmSM["amount"] = amount*1;
				frmSM["operationId"] = gen16CodeId();
				nnfrm["amount"] =amount*2;	
				totalC += amount*1;
				comp2save.push(frmSM)
			}
			else{
				nnfrm["amount"] =amount*1;
				totalC += amount*1;
			}
			
			if(amount*1 >0){
				comp2save.push(nnfrm)
			}
		})


		//let amountBank = parseFloatToDecimal(ffm["amount"],2);
		
		item.otherDeductions && ObjectKeys(item.otherDeductions).map(othDD=>{
			let nnfrm = {...ffm}
			
			let itemODD = item.otherDeductions[othDD];
			let dataAcc = {...getStore("global_account_params")?.[othDD]};
			nnfrm["account"] =  dataAcc["account"];
			nnfrm["subAccount"] = dataAcc["subAccount"];
			nnfrm["operationId"] = gen16CodeId();
			

			
			let amountT = itemODD.amount*1; 

			if(othDD==="Overpayments"){
				nnfrm["type"] ="credit";
				totalC -= amountT*1;
				console.log(othDD, totalC)
				nnfrm["amount"] = amountT *-1;
			}
			else if(othDD==="Underpayments"){
				nnfrm["type"] ="debit";
				totalC += amountT*1;
				console.log(othDD, totalC)
				nnfrm["amount"] = amountT;
			}
			
			comp2save.push(nnfrm)
		})


		let frmSlr = {...ffm}
		
		frmSlr["account"] = getStore("global_account_params")?.salary?.account;

		let amountSlrt = ffm["amount"];
		let amountSlr = parseFloatToDecimal(amountSlrt,2);
		frmSlr["type"] = "debit";
		frmSlr["operationId"] = gen16CodeId();
		frmSlr["amount"] =amountSlr*1;
		comp2save.push(frmSlr)



		let frmBnk = {...ffm}
		frmBnk["account"] = getStore("global_account_params")?.cash_bank.account;
		if(ffm?.futureSlipCheck){
			frmBnk["account"] = getStore("global_account_params")?.futureSlipCheck?.account;
			frmBnk["subAccount"] = getStore("global_account_params")?.futureSlipCheck?.subAccount;
		}

		let amountTBank = ffm["amount"] - totalC ;
		
		if(cash_amount){
			amountTBank = amountTBank - cash_amount;
		}
		let amountBank = parseFloatToDecimal(amountTBank,2);
		frmBnk["type"] = "credit";
		frmBnk["operationId"] = gen16CodeId();
		frmBnk["amount"] =amountBank*1;
		comp2save.push(frmBnk)



		if(cash_amount){
			let frmCashBnk = {...ffm}
			frmCashBnk["account"] = getStore("global_account_params")?.cash_fluid.account;
			let amountCash = parseFloatToDecimal(cash_amount,2);
			frmCashBnk["type"] = "credit";
			frmCashBnk["operationId"] = gen16CodeId();
			frmCashBnk["amount"] =amountCash*1;
			comp2save.push(frmCashBnk)
		}

		let bdyq2 = {...getStore(qryStore())?.add_multi_opera};
		bdyq2.params = commonflds;
		bdyq2.form=comp2save;

		// console.log(bdyq2)
		 fetch2Server(bdyq2, comprobanteId, ffm["document"]);
	
	};

	


	const fetch2Server = async (bdyq2, comprobanteId, document) => {
		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			
			
			setTimeout(() => {
				updStore(frmNm, null)
				//updStore(frmNmW2Manual, null)
				data?.modalID && CloseModal({id:data?.modalID});
				confirm && confirm(comprobanteId, document)
				navigate({
					pathname: "/accounting-ledger" ,
					search: `?cId=${comprobanteId}`
				});
			}, 400);
		}
		/* */
	}


	const closeDetails = (f, v, k) => {
		let hourly = getStore(frmNm)?.["hourly"];
		hourly[f]=v;
		updFrm("hourly",hourly);
	}
	


	
	return (
		<div
		style={{
			maxHeight: "96vh",
			width: "1040px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 25px"
		}}
		className="payStub "
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					Registrar Nomina en la Contabilidad
				</p>
				<div className="flexSpace"/>
				
				<div className="employee_name">
					{item?.name}
				</div>
			</div>

			<div className="_dsplFlx " style={{margin:"10px 10px 10px 0"}}>
				<div className="flexSpace"/>
				<div style={{margin:"14px 10px 0px 0"}}>
					<DateCalComponent  
						init={getStore(frmNm)?.["date"]} 
						label={"Fecha"}
						updDate={(e)=>updFrm("date",e)}
					/>
				</div>
			
				<div className="flexSpace"/>
				<div style={{margin:"30px 0px 0px 0"}}>
					<div className="_dsplFlx " >
						<span className={`checklabel`}>
							{"Cheque a Futuro"}
						</span>
						<CheckBoxSlide
							initvalue={getStore(frmNm)?.["futureSlipCheck"]}
							keyCode={57}
							updChange={(e)=>updFrm("futureSlipCheck",e)}
						/>
					</div>
					
				</div>
				
			<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["document"]} 
					label={"Document"} 
					width={170} 
					updChanges={(e)=>updFrm("document",e)}
				/>
				<div className="flexSpace"/>
				
			
			</div>
			


			<div className="_dsplFlx "  style={{marginTop: 48}} >
				<div className="_dsplFlx " style={{margin:"10px 10px 10px 0"}}>

					{description2}

				</div>
				<div className="flexSpace"/>
				
				<div >
					<GrayButton
						clickHandler={save}
						label={"Guardar"}
						
					/>
				</div>
				
			</div>

			
		</div>
	);
};

export default PaystubEmployee2Accc;
